-- DemandForge AI - initial schema
-- All timestamps are timestamptz. Identifiers are UUIDs generated by Postgres.

create extension if not exists pgcrypto;

-- ---------------------------------------------------------------------------
-- Enumerated domains
-- ---------------------------------------------------------------------------
create type public.user_role as enum ('owner', 'member');

create type public.source_type as enum ('manual', 'chrome_extension', 'meta_api');
create type public.connection_status as enum ('manual_only', 'connected', 'disconnected', 'error');

create type public.budget_status as enum ('unknown', 'unclear', 'stated', 'range');
create type public.signal_level as enum ('unknown', 'low', 'medium', 'high');

create type public.analysis_status as enum ('pending', 'queued', 'analyzing', 'analyzed', 'failed');
create type public.pipeline_status as enum (
  'new', 'shortlisted', 'rejected', 'demo_generated', 'deployed',
  'contacted', 'replied', 'won', 'lost', 'archived'
);

create type public.generation_status as enum ('draft', 'queued', 'generating', 'ready', 'failed', 'approved');
create type public.deployment_status as enum ('not_deployed', 'queued', 'deploying', 'deployed', 'failed');

create type public.job_status as enum ('queued', 'running', 'succeeded', 'failed', 'canceled');
create type public.job_attempt_status as enum ('running', 'succeeded', 'failed');

create type public.deployment_provider as enum ('vercel');
create type public.deployment_run_status as enum ('queued', 'building', 'ready', 'error', 'canceled');

create type public.outreach_channel as enum ('facebook_message', 'email', 'other');
create type public.outreach_status as enum ('draft', 'ready', 'sent', 'replied', 'no_response', 'converted', 'archived');

create type public.ai_usage_status as enum ('success', 'error');

-- ---------------------------------------------------------------------------
-- Shared trigger helpers
-- ---------------------------------------------------------------------------
create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- Profiles (1:1 with auth.users)
-- ---------------------------------------------------------------------------
create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  display_name text not null default '',
  role public.user_role not null default 'member',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint profiles_display_name_length check (char_length(display_name) <= 120)
);

create trigger profiles_set_updated_at
  before update on public.profiles
  for each row execute function public.set_updated_at();

-- The first confirmed owner sets up the workspace. Public sign-up is disabled
-- as soon as a confirmed owner exists, and the profile trigger is made
-- idempotent so repeated invites/confirmations cannot change ownership.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id, display_name, role)
  values (
    new.id,
    coalesce(nullif(new.raw_user_meta_data ->> 'display_name', ''), split_part(coalesce(new.email, 'user'), '@', 1)),
    case
      when exists (select 1 from public.profiles) then 'member'::public.user_role
      when new.raw_user_meta_data ->> 'setup_as_owner' = 'true' then 'owner'::public.user_role
      else 'member'::public.user_role
    end
  )
  on conflict (id) do update
    set display_name = excluded.display_name,
        role = least(profiles.role, excluded.role)::public.user_role;
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ---------------------------------------------------------------------------
-- Sources and collection rules
-- ---------------------------------------------------------------------------
create table public.sources (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  source_type public.source_type not null default 'manual',
  source_name text not null,
  source_url text,
  connection_status public.connection_status not null default 'manual_only',
  config jsonb not null default '{}'::jsonb,
  last_synced_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint sources_name_length check (char_length(source_name) between 1 and 160),
  constraint sources_url_length check (source_url is null or char_length(source_url) <= 2048),
  constraint sources_config_is_object check (jsonb_typeof(config) = 'object')
);

create unique index sources_user_url_unique
  on public.sources (user_id, source_url)
  where source_url is not null;
create index sources_user_created_idx on public.sources (user_id, created_at desc);

create trigger sources_set_updated_at
  before update on public.sources
  for each row execute function public.set_updated_at();

create table public.collection_rules (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  name text not null,
  keywords text[] not null default '{}',
  excluded_keywords text[] not null default '{}',
  project_categories text[] not null default '{}',
  is_enabled boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint collection_rules_name_length check (char_length(name) between 1 and 160),
  constraint collection_rules_keywords_size check (cardinality(keywords) <= 100 and cardinality(excluded_keywords) <= 100),
  constraint collection_rules_categories_size check (cardinality(project_categories) <= 50)
);

create index collection_rules_user_created_idx on public.collection_rules (user_id, created_at desc);

create trigger collection_rules_set_updated_at
  before update on public.collection_rules
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Leads
-- ---------------------------------------------------------------------------
create table public.leads (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  source_id uuid references public.sources (id) on delete set null,
  external_reference text,
  canonical_url text,
  original_text text not null,
  normalized_content_hash text not null,
  project_category text,
  project_title text,
  project_summary text,
  required_features jsonb not null default '[]'::jsonb,
  suggested_features jsonb not null default '[]'::jsonb,
  technology_preferences jsonb not null default '[]'::jsonb,
  budget_status public.budget_status not null default 'unknown',
  budget_amount numeric(12, 2),
  budget_currency char(3),
  urgency public.signal_level not null default 'unknown',
  hiring_intent public.signal_level not null default 'unknown',
  requirements_clarity smallint,
  lead_score integer,
  confidence_score integer,
  evidence jsonb not null default '{}'::jsonb,
  analysis_status public.analysis_status not null default 'pending',
  pipeline_status public.pipeline_status not null default 'new',
  published_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint leads_text_length check (char_length(original_text) between 1 and 20000),
  constraint leads_hash_length check (char_length(normalized_content_hash) = 64),
  constraint leads_scores_range check (
    (requirements_clarity is null or requirements_clarity between 0 and 100) and
    (lead_score is null or lead_score between 0 and 100) and
    (confidence_score is null or confidence_score between 0 and 100)
  ),
  constraint leads_budget_amount_positive check (budget_amount is null or budget_amount >= 0),
  constraint leads_currency_format check (budget_currency is null or budget_currency ~ '^[A-Z]{3}$'),
  constraint leads_features_are_arrays check (
    jsonb_typeof(required_features) = 'array' and
    jsonb_typeof(suggested_features) = 'array' and
    jsonb_typeof(technology_preferences) = 'array'
  ),
  constraint leads_evidence_is_object check (jsonb_typeof(evidence) = 'object')
);

create unique index leads_user_hash_unique on public.leads (user_id, normalized_content_hash);
create unique index leads_user_canonical_url_unique
  on public.leads (user_id, canonical_url)
  where canonical_url is not null;
create index leads_user_created_idx on public.leads (user_id, created_at desc);
create index leads_user_analysis_idx on public.leads (user_id, analysis_status);
create index leads_user_pipeline_idx on public.leads (user_id, pipeline_status);
create index leads_user_score_idx on public.leads (user_id, lead_score desc nulls last);

create trigger leads_set_updated_at
  before update on public.leads
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Demo projects and generated artifacts
-- ---------------------------------------------------------------------------
create table public.demo_projects (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  lead_id uuid not null references public.leads (id) on delete cascade,
  title text not null,
  slug text not null,
  template_name text not null default 'landing',
  generation_status public.generation_status not null default 'draft',
  artifact_storage_path text,
  preview_url text,
  deployment_status public.deployment_status not null default 'not_deployed',
  deployment_url text,
  vercel_project_reference text,
  deployment_error text,
  approved_at timestamptz,
  deployed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint demo_projects_slug_format check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' and char_length(slug) between 3 and 80),
  constraint demo_projects_title_length check (char_length(title) between 1 and 160)
);

create unique index demo_projects_user_slug_unique on public.demo_projects (user_id, slug);
create index demo_projects_user_created_idx on public.demo_projects (user_id, created_at desc);
create index demo_projects_lead_idx on public.demo_projects (lead_id);

create trigger demo_projects_set_updated_at
  before update on public.demo_projects
  for each row execute function public.set_updated_at();

-- Generated files are stored as a validated JSON manifest. This keeps previews
-- and deployments atomic (one row = one approved artifact revision) without
-- exposing object storage credentials to the browser.
create table public.demo_artifacts (
  id uuid primary key default gen_random_uuid(),
  demo_id uuid not null references public.demo_projects (id) on delete cascade,
  files jsonb not null,
  manifest jsonb not null default '{}'::jsonb,
  byte_size integer not null default 0,
  checksum text not null,
  created_at timestamptz not null default now(),
  constraint demo_artifacts_files_is_object check (jsonb_typeof(files) = 'object'),
  constraint demo_artifacts_manifest_is_object check (jsonb_typeof(manifest) = 'object'),
  constraint demo_artifacts_byte_size_range check (byte_size >= 0 and byte_size <= 2097152)
);

create unique index demo_artifacts_demo_unique on public.demo_artifacts (demo_id);

-- ---------------------------------------------------------------------------
-- Durable background jobs
-- ---------------------------------------------------------------------------
create table public.jobs (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  job_type text not null,
  status public.job_status not null default 'queued',
  payload jsonb not null default '{}'::jsonb,
  idempotency_key text,
  attempt_count integer not null default 0,
  max_attempts integer not null default 3,
  scheduled_at timestamptz not null default now(),
  started_at timestamptz,
  completed_at timestamptz,
  last_error text,
  locked_by text,
  locked_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint jobs_type_length check (char_length(job_type) between 1 and 80),
  constraint jobs_payload_is_object check (jsonb_typeof(payload) = 'object'),
  constraint jobs_attempts_non_negative check (
    attempt_count >= 0 and max_attempts between 1 and 10
  ),
  constraint jobs_idempotency_key_length check (
    idempotency_key is null or char_length(idempotency_key) <= 200
  )
);

create unique index jobs_idempotency_key_unique
  on public.jobs (idempotency_key)
  where idempotency_key is not null;
create index jobs_claim_idx on public.jobs (status, scheduled_at) where status = 'queued';
create index jobs_user_created_idx on public.jobs (user_id, created_at desc);
create index jobs_stale_idx on public.jobs (status, locked_at) where status = 'running';

create trigger jobs_set_updated_at
  before update on public.jobs
  for each row execute function public.set_updated_at();

create table public.job_attempts (
  id uuid primary key default gen_random_uuid(),
  job_id uuid not null references public.jobs (id) on delete cascade,
  attempt integer not null,
  worker_id text not null,
  status public.job_attempt_status not null default 'running',
  started_at timestamptz not null default now(),
  finished_at timestamptz,
  error text,
  constraint job_attempts_attempt_positive check (attempt >= 1)
);

create unique index job_attempts_job_attempt_unique on public.job_attempts (job_id, attempt);
create index job_attempts_job_idx on public.job_attempts (job_id, started_at desc);

-- ---------------------------------------------------------------------------
-- Deployment history
-- ---------------------------------------------------------------------------
create table public.deployments (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  demo_project_id uuid not null references public.demo_projects (id) on delete cascade,
  provider public.deployment_provider not null default 'vercel',
  vercel_deployment_id text,
  vercel_project_reference text,
  status public.deployment_run_status not null default 'queued',
  url text,
  error_message text,
  requested_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  completed_at timestamptz
);

create index deployments_demo_idx on public.deployments (demo_project_id, created_at desc);
create index deployments_user_idx on public.deployments (user_id, created_at desc);
create unique index deployments_vercel_id_unique
  on public.deployments (vercel_deployment_id)
  where vercel_deployment_id is not null;

create trigger deployments_set_updated_at
  before update on public.deployments
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Outreach
-- ---------------------------------------------------------------------------
create table public.outreach_records (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  lead_id uuid not null references public.leads (id) on delete cascade,
  demo_project_id uuid references public.demo_projects (id) on delete set null,
  channel public.outreach_channel not null default 'facebook_message',
  draft_content text not null,
  status public.outreach_status not null default 'draft',
  sent_at timestamptz,
  response_at timestamptz,
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint outreach_draft_length check (char_length(draft_content) between 1 and 8000),
  constraint outreach_notes_length check (notes is null or char_length(notes) <= 4000)
);

create index outreach_user_created_idx on public.outreach_records (user_id, created_at desc);
create index outreach_lead_idx on public.outreach_records (lead_id, created_at desc);
create index outreach_user_status_idx on public.outreach_records (user_id, status);

create trigger outreach_set_updated_at
  before update on public.outreach_records
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- AI usage and audit trail
-- ---------------------------------------------------------------------------
create table public.ai_usage (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  provider text not null default 'google',
  model text not null,
  operation text not null,
  input_usage integer not null default 0,
  output_usage integer not null default 0,
  estimated_cost numeric(12, 6) not null default 0,
  status public.ai_usage_status not null default 'success',
  error_code text,
  created_at timestamptz not null default now(),
  constraint ai_usage_token_counts check (input_usage >= 0 and output_usage >= 0),
  constraint ai_usage_cost_non_negative check (estimated_cost >= 0)
);

create index ai_usage_user_created_idx on public.ai_usage (user_id, created_at desc);

create table public.audit_events (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  actor_type text not null default 'user',
  action text not null,
  entity_type text not null,
  entity_id uuid,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  constraint audit_events_metadata_is_object check (jsonb_typeof(metadata) = 'object')
);

create index audit_events_user_created_idx on public.audit_events (user_id, created_at desc);
create index audit_events_entity_idx on public.audit_events (entity_type, entity_id);

-- ---------------------------------------------------------------------------
-- Extension API tokens (only a SHA-256 hash is stored)
-- ---------------------------------------------------------------------------
create table public.api_tokens (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  name text not null,
  token_hash text not null,
  token_prefix text not null,
  last_used_at timestamptz,
  revoked_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint api_tokens_name_length check (char_length(name) between 1 and 120),
  constraint api_tokens_hash_length check (char_length(token_hash) = 64)
);

create unique index api_tokens_hash_unique on public.api_tokens (token_hash);
create index api_tokens_user_idx on public.api_tokens (user_id, created_at desc);

create trigger api_tokens_set_updated_at
  before update on public.api_tokens
  for each row execute function public.set_updated_at();
